corpus_block("test-coord_sf.R: default crs works", {
  skip_if_not_installed("sf")
  polygon <- sf::st_sfc(
      sf::st_polygon(list(matrix(c(-80, -76, -76, -80, -80, 35, 35, 40, 40, 35), ncol = 2))),
      crs = 4326 # basic long-lat crs
    )
  polygon <- sf::st_transform(polygon, crs = 3347)
  points <- data_frame(
      x = c(-80, -80, -76, -76),
      y = c(35, 40, 35, 40)
    )
  .plot("test-coord_sf.R: default crs works #1", p <- ggplot(polygon) + geom_sf(fill = NA))
  .plot("test-coord_sf.R: default crs works #2", p + xlim(-Inf, 80))
  points_trans <- sf_transform_xy(points, 3347, 4326)
  .plot("test-coord_sf.R: default crs works #3", p + geom_point(data = points_trans, aes(x, y)))
  .plot("test-coord_sf.R: default crs works #4", p + geom_point(data = points, aes(x, y)) + coord_sf(default_crs = 4326))
  .plot("test-coord_sf.R: default crs works #5", p + geom_point(data = points, aes(x, y)) + coord_sf(xlim = c(-80.5, -76), ylim = c(36, 
      41), default_crs = 4326))
  lims <- sf_transform_xy(
      list(x = c(-80.5, -76, -78.25, -78.25), y = c(38.5, 38.5, 36, 41)),
      3347, 4326
    )
  .plot("test-coord_sf.R: default crs works #6", p + geom_point(data = points_trans, aes(x, y)) + coord_sf(xlim = lims$x[1:2], ylim = lims$y[3:4]))
})

